//! Candle's elementwise CUDA kernels, as PTX generated by cuda-oxide.
//!
//! The PTX is generated offline and committed, so this crate depends on
//! neither cuda-oxide nor pliron and needs no build script. Regenerate with
//! `cargo xtask gen-ptx` from the workspace this crate is developed in.
//!
//! Load a module through `CudaDevice::get_or_load_custom_func`, keyed by the
//! module name below. Do not route it through `candle_kernels::Module`, whose
//! index is positional into a fixed array and would collide.

/// PTX holding every binary entry point.
pub const BINARY: &str = include_str!("../ptx/binary.ptx");

/// PTX holding every unary entry point.
pub const UNARY: &str = include_str!("../ptx/unary.ptx");

/// Key for `get_or_load_custom_func` when loading [`BINARY`].
pub const BINARY_MODULE: &str = "oxide::binary";

/// Key for `get_or_load_custom_func` when loading [`UNARY`].
pub const UNARY_MODULE: &str = "oxide::unary";

/// Every entry point in [`BINARY`].
pub const BINARY_ENTRIES: &[&str] = &[
    "badd_f32",
    "badd_f64",
    "bsub_f32",
    "bsub_f64",
    "bmul_f32",
    "bmul_f64",
    "bdiv_f32",
    "bdiv_f64",
    "bmaximum_f32",
    "bmaximum_f64",
    "bminimum_f32",
    "bminimum_f64",
    "eq_f32",
    "eq_f64",
    "ne_f32",
    "ne_f64",
    "lt_f32",
    "lt_f64",
    "le_f32",
    "le_f64",
    "gt_f32",
    "gt_f64",
    "ge_f32",
    "ge_f64",
];

/// Every entry point in [`UNARY`].
pub const UNARY_ENTRIES: &[&str] = &[
    "ucopy_f32",
    "ucopy_f64",
    "uneg_f32",
    "uneg_f64",
    "usqr_f32",
    "usqr_f64",
    "urecip_f32",
    "urecip_f64",
    "uabs_f32",
    "uabs_f64",
    "usqrt_f32",
    "usqrt_f64",
    "uexp_f32",
    "uexp_f64",
    "ulog_f32",
    "ulog_f64",
    "usin_f32",
    "usin_f64",
    "ucos_f32",
    "ucos_f64",
    "utanh_f32",
    "utanh_f64",
];

/// Whether `module` provides `name`. Returns false for an unknown module.
pub fn has_entry(module: &str, name: &str) -> bool {
    match module {
        BINARY_MODULE => BINARY_ENTRIES.contains(&name),
        UNARY_MODULE => UNARY_ENTRIES.contains(&name),
        _ => false,
    }
}

/// The PTX for `module`, or `None` if the name is not one of this crate's.
pub fn ptx_for(module: &str) -> Option<&'static str> {
    match module {
        BINARY_MODULE => Some(BINARY),
        UNARY_MODULE => Some(UNARY),
        _ => None,
    }
}
